INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66178179', 66178179, 'analyze_legacy', 'Kementerian Koordinator Bidang Hukum, Hak Asasi Manusia, Imigrasi, dan Pemasyarakatan', 'central', 'Kementerian Koordinator Bidang Hukum Hak Asasi Manusia Imigrasi dan Pemasyarakatan', 'Paket Meeting Fullboard Sinkronisasi dan Koordinasi Kebijakan Rekomendasi kebijakan capaian kinerja dan penyelesaian permasalahan lintas K/L terkait pendidikan HAM', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 103548000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 20, OP, @ 1347000 ) ( 64, OP, @ 1197000 )', '1. Biaya Paket Meeting Fullboard Pejabat Eselon I dan II ( 20, OP, @ 1347000 ); 2. Biaya Paket Meeting Fullboard Pejabat Eselon I dan III ( 64, OP, @ 1197000 );', 'Spesifikasi Teknis: Paket Meeting Fullboard (3 Hari 2 Malam) 1. Informasi Umum Jenis Pekerjaan: Jasa Penyelenggaraan Paket Meeting (Fullboard) Lokasi: Hotel di wilayah Jakarta (Minimal Bintang 4) Durasi: 3 Hari 2 Malam Tahun Anggaran: 2026 2. Rincian Ruang Lingkup Pekerjaan A. Kamar Penginapan Tipe Kamar: Twin Sharing (1 kamar untuk 2 orang) atau Single Occupancy (sesuai kebutuhan kebijakan). Fasilitas Kamar: AC, kamar mandi dalam (shower hot/cold), perlengkapan mandi, akses Wi-Fi gratis, dan sarapan pagi (Breakfast). Ketentuan: Kamar harus dalam kondisi bersih, bebas asap rokok (non-smoking room), dan sudah siap (ready) saat waktu check-in. B. Ruang Rapat & Fasilitas Utama Kapasitas: Mampu menampung jumlah peserta sesuai daftar (misal: 50 - 100 orang) dengan menjaga jarak nyaman. Pengaturan Meja: U-Shape, Classroom, atau Round Table (sesuai instruksi user). Fasilitas Standar: Sistem Tata Suara (Sound System) standar meeting dengan minimal 2-4 unit wireless microphone. LCD Projector dan Screen (minimal 2 unit jika ruangan luas). Flipchart dengan spidol. Akses Wi-Fi High Speed khusus di dalam ruang rapat. Meeting Kit standar hotel (Note pad, Pulpen, Air mineral, dan Permen). C. Konsumsi (Catering) Selama 3 hari, vendor wajib menyediakan: Hari ke-1: 1x Makan Siang, 2x Coffee Break, 1x Makan Malam. Hari ke-2: 1x Sarapan (Include Kamar), 2x Coffee Break, 1x Makan Siang, 1x Makan Malam. Hari ke-3: 1x Sarapan (Include Kamar), 2x Coffee Break, 1x Makan Siang. Menu: Prasmanan (Buffet) dengan variasi menu Nusantara atau Internasional yang higienis dan memiliki sertifikat Halal. 3. Standar Pelayanan & Kualitas Kebersihan: Seluruh area (ruang rapat, kamar, toilet) harus memenuhi standar protokol kesehatan dan kebersihan yang berlaku. Personel Pendamping: Pihak hotel wajib menyediakan minimal 1 (satu) orang Banquet Captain atau Event Coordinator yang siap sedia (standby) selama acara berlangsung untuk menangani kendala teknis. Lokasi: Strategis di Jakarta, mudah diakses oleh transportasi umum, dan memiliki area parkir yang memadai. 4. Ketentuan Administrasi & Pembayaran Pemesanan: Dilakukan melalui Surat Pesanan (SP) atau Kontrak. Pembayaran: Pembayaran dilakukan setelah seluruh rangkaian acara selesai (termin sesuai progres pekerjaan) berdasarkan Berita Acara Serah Terima (BAST) yang ditandatangani kedua belah pihak. Pajak: Harga yang ditawarkan sudah termasuk Pajak Pertambahan Nilai (PPN) dan Pajak Daerah (PB1) sesuai ketentuan yang berlaku.', 0, 'med', NULL, NULL, NULL, 2, 1, 1, 1, 1, 2570277);
