INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66179350', 66179350, 'analyze_legacy', 'Kab. Madiun', 'kabkota', 'Dinas Pekerjaan Umum dan Penataan Ruang', 'Jasa Konsultansi Perencanaan Rehabilitasi Jalan Paket 5', 'Jasa Konsultansi', 'Pengadaan Langsung', 'Jawa Timur, Madiun (Kab.)', 87000000, 'March 2026', 'APBD', 1, 1, '1 Paket', 'Pekerjaan Perencanaan Rehabilitasi Jalan, mempersiapkan informasi berupa data teknik, biaya, dan rekomendasi bagi Pejabat Pembuat Komitmen (PPK) untuk mencegah tidak terpenuhinya standar-standar sesuai peraturan yang berlaku. Kinerja perencanaan harus memenuhi standar hasil kerja perencanaan yang disyaratkan. Tanggung jawab profesional perencanaan ini tidak hanya pada Penyedia Jasa Konsultansi sebagai perusahaan tetapi juga bagi para Tenaga Ahli perencanaan yang terlibat. Penyedia Jasa Konsultansi dan Tenaga Ahli yang dimaksud selain berpengalaman di bidangnya, harus mempunyai lisensi dalam bentuk sertifikat kualifikasi di bidang teknis jalan.', 'Pekerjaan Perencanaan Rehabilitasi Jalan meliputi lokasi: Ruas Dempelan - Bts. Kota Madiun (081), Ruas Nglanduk - Bts. Kota Madiun (082), Ruas Sumberejo - Bts. Kota Madiun (083), Ruas Rejosari - Bts. Kota Madiun (084), Ruas Nglambangan - Betek (367), Ruas Jln. Wijaya (585.11K) dengan melibatkan 2 orang Tenaga Ahli yaitu 1 orang Team Leader dan 1 Orang Ahli K3 Konstruksi. 6 Orang Tenaga pendukung yaitu 4 orang surveyor, 1 orang juru gambar dan 1 orang tenaga administrasi. Dengan Pagu anggaran Rp. 87.000.000', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2572434);
