INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66134274', 66134274, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Penyusunan Kajian Optimalisasi Penerimaan Negara, Belanja Berkualitas, dan Pembiayaan Pembangunan Lingkup Bidang Perencanaan Fiskal, Moneter dan Sektor Keuangan TA 2026', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 75000000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '10 Bulan', 'a. Menyusun dan menyediakan analisis substantif untuk mendukung perumusan kebijakan fiskal yang berfokus pada optimalisasi penerimaan negara, peningkatan kualitas belanja, dan penguatan pembiayaan pembangunan; b. Melakukan pengumpulan, pengolahan, pemodelan, dan analisis data makrofiskal terkait pendapatan negara, belanja negara, dan pembiayaan pembangunan guna menghasilkan rekomendasi kebijakan berbasis data dan bukti empiris; c. Melakukan pemantauan dan pengawalan perkembangan kebijakan serta isu strategis fiskal nasional dan daerah, termasuk dinamika kinerja APBN dan risiko fiskal; d. Menyusun laporan bulanan kinerja APBN dan laporan triwulanan kondisi fiskal sebagai bahan masukan kebijakan dan perencanaan pembangunan; e. Menyusun rancangan awal analisis dan rekomendasi kebijakan terkait optimalisasi penerimaan negara, belanja berkualitas, dan pembiayaan pembangunan, termasuk kajian jangka menengah dan panjang; f. Berkontribusi dalam penyusunan naskah kajian tematik dan bunga rampai “The Role of Fiscal Policy to Achieve Indonesia’s Golden Vision 2045: Selected Studies on Policy Reform”, serta mendukung pelaksanaan diseminasi dan pemanfaatan hasil kajian tersebut sebagai bahan komunikasi dan perumusan kebijakan fiskal; g. Membantu pengawalan penyusunan, harmonisasi, serta evaluasi regulasi yang terkait dengan kebijakan fiskal, khususnya di bidang penerimaan, belanja, dan pembiayaan; h. Membantu penyusunan bahan komunikasi kebijakan fiskal untuk publik dan pemangku kepentingan, termasuk policy brief, ringkasan eksekutif, dan substansi media sosial direktorat; i. Mendukung penyusunan bahan masukan kebijakan fiskal untuk dokumen perencanaan dan penganggaran pembangunan nasional, termasuk RKP dan dokumen pendukung lainnya; j. Mendukung koordinasi dan sinergi lintas kementerian/lembaga dan pemerintah daerah dalam perumusan dan implementasi kebijakan fiskal; k. Menyusun dan berkontribusi dalam kajian Public Finance Review (PFR) sebagai bahan evaluasi menyeluruh atas kinerja fiskal, efektivitas belanja, dan keberlanjutan pembiayaan pembangunan; l. Melaksanakan penugasan lain yang diberikan oleh pimpinan sesuai dengan kebutuhan organisasi.', 'a. Memiliki latar belakang pendidikan minimal lulusan sarjana (S1) Ekonomi Studi Pembangunan; b. Memiliki kompetensi sesuai bidang yang dipersyaratkan dibuktikan dengan ijazah jenjang pendidikan, sertifikat keahlian/teknis, dan/atau sertifikat pelatihan/kursus; c. Memiliki pengalaman paling kurang 4 (empat) tahun terkait analisis keuangan negara; d. Memiliki pengalaman pekerjaan sejenis (jenis pekerjaan, kompleksitas pekerjaan, metodologi, teknologi, atau karakteristik lainnya yang bisa menggambarkan kesamaan); e. Nilai pekerjaan sejenis tertinggi dalam kurun waktu 10 (sepuluh) tahun terakhir paling kurang sama dengan 50% (lima puluh persen) nilai HPS/Pagu Anggaran; f. Tidak sedang berada dalam kontrak/perjanjian bekerja penuh waktu lain; g. Bersedia bekerja di luar jam kantor dan dalam jadwal ketat; h. Lebih diutamakan pernah melakukan presentasi terkait hasil analisis di forum publik/internal, dapat dibuktikan dengan dokumentasi hasil pekerjaan/tautan hasil pekerjaan; dan i. Lebih diutamakan pernah bekerjasama dengan pemerintah pusat maupun Pemerintah Daerah dapat dibuktikan dengan dokumentasi hasil pekerjaan/tautan hasil pekerjaan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2575057);
