INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66133857', 66133857, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Penyusunan Strategi Penguatan Kebijakan Moneter Dalam Rangka Persiapan Perumusan Rekomendasi Kebijakan Bidang Perencanaan Fiskal, Moneter dan Sektor Keunagan TA 2026', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 75000000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '10 Bulan', 'a. Mengkoordinasikan substansi dan teknis pelaksanaan diseminasi hasil kajian Listening to Indonesia Survei; b. Membuat laporan komprehensif terkait fenomena inflasi harga pangan bergejolak beras; c. Membuat laporan analisis bulanan dan triwulanan mengenai perkembangan inflasi; d. Membuat Quick Response Analysis mengenai perkembangan isu moneter meliputi inflasi, nilai tukar, dan intervensi kebijakan moneter konvensional maupun non-konvensional; e. Mendukung pelaksanaan Monitoring dan Evaluasi Pengendalian Inflasi dalam rangka memperkuat fungsi direktorat dalam keanggotaan Tim Pengendalian Inflasi Pusat (TPIP); f. Mendukung penguatan pengolahan dan pemodelan data makroekonomi guna menghasilkan rekomendasi kebijakan moneter ysang berbasis data; g. Membantu mengawal sinkronisasi target indikator inflasi pusat dan daerah dalam dokumen perencanaan; h. Menyusun dokumen penyusunan analisis dampak dan efektivitas kebijakan pengendalian inflasi harga diatur pemerintah (administered prices); i. Menyusun dokumen studi komparatif rekomendasi kebijakan moneter nasional dan internasional; j. Menyusun rancangan kajian analisis efektivitas kebijakan moneter terhadap sektor rill; k. Menyusun rancangan kajian analisis penguatan nilai tukar melalui penguatan hilirisasi dan Devisa Hasil Ekspor (DHE) SDA; l. Penyusunan draft kompilasi kajian isu moneter sepanjang tahun 2026.', 'a. Memiliki latar belakang pendidikan minimal lulusan sarjana (S1) Ekonomi Studi Pembangunan; b. Memiliki kompetensi sesuai bidang yang dipersyaratkan dibuktikan dengan ijazah jenjang pendidikan, sertifikat keahlian/teknis, dan/atau sertifikat pelatihan/kursus; c. Memiliki pengalaman paling kurang 3 (tiga) tahun terkait analisis fiskal, moneter, dan sektor keuangan; d. Memiliki pengalaman pekerjaan sejenis (jenis pekerjaan, kompleksitas pekerjaan, metodologi, teknologi, atau karakteristik lainnya yang bisa menggambarkan kesamaan); e. Nilai pekerjaan sejenis tertinggi dalam kurun waktu 10 (sepuluh) tahun terakhir paling kurang sama dengan 50% (lima puluh persen) nilai HPS/Pagu Anggaran; f. Tidak sedang berada dalam kontrak/perjanjian bekerja penuh waktu lain; g. Bersedia bekerja di luar jam kantor dan dalam jadwal ketat; h. Lebih diutamakan pernah melakukan presentasi terkait hasil analisis di forum publik/internal, dapat dibuktikan dengan dokumentasi hasil pekerjaan/tautan hasil pekerjaan; dan i. Lebih diutamakan pernah bekerjasama dengan pemerintah pusat maupun Pemerintah Daerah dapat dibuktikan dengan dokumentasi hasil pekerjaan/tautan hasil pekerjaan. j. Memiliki pengalaman paling kurang 1 (satu) pekerjaan dalam kurun waktu 4 (empat) tahun terakhir baik di lingkungan pemerintah maupun swasta, termasuk pengalaman subkontrak.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2577327);
